{
  "name": "inkos-workers",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "engines": {
    "node": ">=20.0.0"
  },
  "scripts": {
    "jobs": "tsx workers/jobs/index.ts",
    "cron": "tsx workers/cron/index.ts",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "bullmq": "^5.51.6",
    "node-cron": "^3.0.3",
    "pino": "9.6.0",
    "twilio": "^5.13.1",
    "resend": "^6.12.0",
    "@react-email/components": "^1.0.12",
    "@sentry/node": "^10.49.0",
    "@supabase/supabase-js": "2.103.1",
    "zod": "3.25.67"
  },
  "devDependencies": {
    "@types/node": "22.15.3",
    "@types/node-cron": "^3.0.11",
    "tsx": "^4.19.4",
    "typescript": "5.8.3"
  }
}

/**
 * Worker env validation — Zod boot-time check.
 * Workers never import from next/* — standalone validation only.
 */
import { z } from 'zod'

const workerEnvSchema = z.object({
  NODE_ENV: z.enum(['production', 'development', 'test']).default('development'),
  LOG_LEVEL: z.enum(['trace', 'debug', 'info', 'warn', 'error', 'fatal']).default('info'),

  NEXT_PUBLIC_SUPABASE_URL: z.string().url(),
  SUPABASE_SERVICE_ROLE_KEY: z.string().min(1),

  REDIS_URL: z.string().url(),

  // Twilio (all optional — worker skips SMS if absent)
  TWILIO_ACCOUNT_SID: z.string().optional(),
  TWILIO_AUTH_TOKEN: z.string().optional(),
  TWILIO_PHONE_NUMBER: z.string().optional(),

  // Resend
  RESEND_API_KEY: z.string().optional(),
  RESEND_FROM_EMAIL: z.string().default('notifications@inkos.app'),
  RESEND_REPLY_TO: z.string().default('support@inkos.app'),

  // Sentry
  SENTRY_DSN: z.string().optional(),

  // App URL (for email links)
  NEXT_PUBLIC_APP_URL: z.string().url().default('http://localhost:3100'),
})

function createWorkerEnv() {
  const result = workerEnvSchema.safeParse(process.env)
  if (!result.success) {
    const formatted = result.error.format()
    throw new Error(
      `[InkOS Workers] Invalid environment variables:\n${JSON.stringify(formatted, null, 2)}`,
    )
  }
  return result.data
}

export const workerEnv = createWorkerEnv()

/**
 * Structured pino logger for worker services.
 * Mirrors the web app logger but with service: 'inkos-workers'.
 */
import pino from 'pino'

export const logger = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  formatters: {
    level: (label) => ({ level: label }),
  },
  base: {
    env: process.env.NODE_ENV ?? 'development',
    service: 'inkos-workers',
    version: process.env.RAILWAY_DEPLOYMENT_ID ?? 'local',
  },
  redact: {
    paths: [
      '*.password',
      '*.token',
      '*.api_key',
      '*.apiKey',
      '*.secret',
      '*.webhook_key',
      '*.authToken',
    ],
    censor: '[REDACTED]',
  },
  timestamp: pino.stdTimeFunctions.isoTime,
  ...(process.env.NODE_ENV === 'development' && {
    transport: {
      target: 'pino-pretty',
      options: {
        colorize: true,
        translateTime: 'HH:MM:ss',
        ignore: 'pid,hostname',
      },
    },
  }),
})

/**
 * Supabase service-role client for workers.
 * Bypasses RLS — only use in cron jobs and worker services.
 * NEVER export or use this in user-facing code.
 *
 * Workers never import from next/* — uses @supabase/supabase-js directly.
 */
import { createClient } from '@supabase/supabase-js'
import { workerEnv } from './env.js'

// Shared singleton — workers are long-running processes, single instance is fine.
export const supabase = createClient(
  workerEnv.NEXT_PUBLIC_SUPABASE_URL,
  workerEnv.SUPABASE_SERVICE_ROLE_KEY,
  {
    auth: {
      autoRefreshToken: false,
      persistSession: false,
    },
  },
)

/**
 * Sentry initialisation for worker services.
 * Import this at the top of every worker entry point.
 */
import * as Sentry from '@sentry/node'

export function initSentry() {
  const dsn = process.env.SENTRY_DSN
  if (!dsn) return

  Sentry.init({
    dsn,
    environment: process.env.NODE_ENV ?? 'development',
    release: process.env.RAILWAY_DEPLOYMENT_ID ?? 'local',
    tracesSampleRate: 0.1,
  })
}

export { Sentry }

/**
 * send-sms BullMQ worker.
 *
 * Consumes the 'send-sms' queue.
 * Job payload: { commId: string; studioId: string }
 *   commId  — client_communications.id row to process
 *   studioId — used for routing & logging context
 *
 * Idempotent: skips jobs where status is already sent/delivered/failed.
 * Retry strategy: 3 attempts, exponential backoff (5s base), dead-letter on final failure.
 */
import { Worker } from 'bullmq'
import { Twilio } from 'twilio'
import { supabase } from '../lib/supabase.js'
import { logger } from '../lib/logger.js'
import { workerEnv } from '../lib/env.js'
import { Sentry } from '../lib/sentry.js'

const QUEUE_NAME = 'inkos-jobs'
const JOB_NAME = 'send-sms'

// ─── Payload type ─────────────────────────────────────────────────────────────

interface SendSmsPayload {
  commId: string
  studioId: string
}

function isSendSmsPayload(data: unknown): data is SendSmsPayload {
  return (
    typeof data === 'object' &&
    data !== null &&
    typeof (data as Record<string, unknown>)['commId'] === 'string' &&
    typeof (data as Record<string, unknown>)['studioId'] === 'string'
  )
}

// ─── Twilio client (lazy) ────────────────────────────────────────────────────

let _twilio: Twilio | null = null

function getTwilioClient(): Twilio | null {
  if (!workerEnv.TWILIO_ACCOUNT_SID || !workerEnv.TWILIO_AUTH_TOKEN) return null
  if (!_twilio) {
    _twilio = new Twilio(workerEnv.TWILIO_ACCOUNT_SID, workerEnv.TWILIO_AUTH_TOKEN)
  }
  return _twilio
}

// ─── Worker ──────────────────────────────────────────────────────────────────

export function createSendSmsWorker() {
  const worker = new Worker(
    QUEUE_NAME,
    async (job) => {
      if (job.name !== JOB_NAME) return

      if (!isSendSmsPayload(job.data)) {
        logger.error({ jobId: job.id, data: job.data }, 'send-sms: invalid payload shape — skipping')
        return
      }

      const { commId, studioId } = job.data

      const workerLog = logger.child({ jobId: job.id, commId, studioId })
      workerLog.info('send-sms: processing')

      // ── 1. Fetch communication row ────────────────────────────────────────
      const { data: comm, error: commErr } = await supabase
        .from('client_communications')
        .select('id, status, body, client_id, studio_id, channel')
        .eq('id', commId)
        .single()

      if (commErr || !comm) {
        workerLog.error({ err: commErr }, 'send-sms: comm row not found')
        throw new Error(`comm row not found: ${commId}`)
      }

      if (comm.channel !== 'sms') {
        workerLog.warn({ channel: comm.channel }, 'send-sms: comm row is not sms channel — skipping')
        return
      }

      // ── 2. Idempotency guard ──────────────────────────────────────────────
      const terminalStatuses = ['sent', 'delivered', 'failed', 'bounced'] as const
      if (terminalStatuses.includes(comm.status as typeof terminalStatuses[number])) {
        workerLog.info({ status: comm.status }, 'send-sms: already in terminal state — skipping (idempotent)')
        return
      }

      // ── 3. Resolve client phone number ────────────────────────────────────
      const { data: client, error: clientErr } = await supabase
        .from('clients')
        .select('phone, first_name')
        .eq('id', comm.client_id)
        .single()

      if (clientErr || !client?.phone) {
        workerLog.warn({ clientId: comm.client_id }, 'send-sms: client has no phone — marking failed')
        await supabase
          .from('client_communications')
          .update({ status: 'failed', error: 'Client has no phone number on record', updated_at: new Date().toISOString() })
          .eq('id', commId)
        return
      }

      // ── 4. Resolve studio From number ─────────────────────────────────────
      const { data: studio } = await supabase
        .from('studios')
        .select('twilio_phone_number')
        .eq('id', studioId)
        .single()

      const fromNumber = studio?.twilio_phone_number ?? workerEnv.TWILIO_PHONE_NUMBER

      if (!fromNumber) {
        workerLog.error('send-sms: no From number available (studio.twilio_phone_number + TWILIO_PHONE_NUMBER both absent)')
        await supabase
          .from('client_communications')
          .update({ status: 'failed', error: 'No Twilio From number configured', updated_at: new Date().toISOString() })
          .eq('id', commId)
        return
      }

      // ── 5. Send via Twilio ────────────────────────────────────────────────
      const twilioClient = getTwilioClient()
      if (!twilioClient) {
        workerLog.warn('send-sms: Twilio not configured — dropping job')
        await supabase
          .from('client_communications')
          .update({ status: 'failed', error: 'Twilio not configured (TWILIO_ACCOUNT_SID/TWILIO_AUTH_TOKEN missing)', updated_at: new Date().toISOString() })
          .eq('id', commId)
        return
      }

      try {
        const message = await twilioClient.messages.create({
          from: fromNumber,
          to: client.phone,
          body: comm.body,
        })

        workerLog.info({ sid: message.sid, status: message.status }, 'send-sms: sent via Twilio')

        await supabase
          .from('client_communications')
          .update({
            status: 'sent',
            provider_message_id: message.sid,
            sent_at: new Date().toISOString(),
            error: null,
            updated_at: new Date().toISOString(),
          })
          .eq('id', commId)

      } catch (err: unknown) {
        const errMsg = err instanceof Error ? err.message : String(err)
        workerLog.error({ err }, 'send-sms: Twilio send failed')
        Sentry.captureException(err, { extra: { commId, studioId, jobId: job.id } })

        await supabase
          .from('client_communications')
          .update({
            status: 'failed',
            error: errMsg,
            updated_at: new Date().toISOString(),
          })
          .eq('id', commId)

        // Re-throw so BullMQ retries (3 attempts with exponential backoff)
        throw err
      }
    },
    {
      connection: {
        url: workerEnv.REDIS_URL,
        maxRetriesPerRequest: null,
      },
      concurrency: 5,
      // Retry: 3 attempts, exponential backoff, 5s base → 5s / 25s / 125s
      // Configured on the Queue side (lib/queue.ts defaultJobOptions) — no override needed here
    },
  )

  worker.on('completed', (job) => {
    logger.info({ jobId: job.id, jobName: job.name }, 'send-sms worker: job completed')
  })

  worker.on('failed', (job, err) => {
    logger.error({ jobId: job?.id, err }, 'send-sms worker: job failed')
  })

  worker.on('error', (err) => {
    logger.error({ err }, 'send-sms worker: worker error')
    Sentry.captureException(err)
  })

  return worker
}

/**
 * Auto-cancel cron — unpaid deposits.
 *
 * Runs every 10 minutes.
 * Finds bookings where:
 *   - status = 'pending'
 *   - deposit_paid = false
 *   - deposit_cents > 0 (deposit was required)
 *   - scheduled_at > now() (appointment hasn't happened yet)
 *   - deadline has passed: now() > COALESCE(deposit_deadline_override, created_at + deadline_hours * '1 hour')
 *
 * For each matched booking:
 *   1. Sets status = 'cancelled', cancelled_at = now()
 *   2. Enqueues send-email job (booking_auto_cancelled template)
 *   3. Enqueues send-sms job if client has phone (optional — graceful skip)
 *   4. Logs cancellation
 */
import { supabase } from '../lib/supabase.js'
import { logger } from '../lib/logger.js'
import { Sentry } from '../lib/sentry.js'
import { enqueueJob } from '../lib/queue.js'

// ─── Types ───────────────────────────────────────────────────────────────────

interface CancelledBookingRow {
  id: string
  studio_id: string
  client_id: string
  deposit_cents: number
  scheduled_at: string
  cancelled_at: string | null
  client: {
    first_name: string
    last_name: string | null
    email: string | null
    phone: string | null
  } | null
  artist: {
    display_name: string
  } | null
  service: {
    name: string
  } | null
  studio: {
    name: string
    deposit_deadline_hours: number | null
  } | null
  comm_row: {
    id: string
  } | null
}

// ─── Main handler ────────────────────────────────────────────────────────────

export async function runAutoCancelDeposits(): Promise<void> {
  const runLog = logger.child({ cron: 'auto-cancel-deposits' })
  runLog.info('auto-cancel: checking for overdue deposits')

  Sentry.addBreadcrumb({ message: 'auto-cancel-deposits: run start', level: 'info' })

  try {
    // ── 1. Find overdue bookings ─────────────────────────────────────────────
    // Use RPC to leverage the deposit_deadline_hours studio setting and override column.
    // The query uses COALESCE(deposit_deadline_override, created_at + deadline_hours * interval '1 hour')
    // as the effective deadline.

    const { data: overdueBookings, error: fetchErr } = await supabase
      .rpc('get_overdue_deposit_bookings')

    if (fetchErr) {
      runLog.error({ err: fetchErr }, 'auto-cancel: failed to fetch overdue bookings')
      Sentry.captureException(fetchErr, { tags: { cron: 'auto-cancel-deposits' } })
      return
    }

    const bookings = (overdueBookings ?? []) as CancelledBookingRow[]

    if (bookings.length === 0) {
      runLog.info('auto-cancel: no overdue bookings found')
      return
    }

    runLog.info({ count: bookings.length }, 'auto-cancel: found overdue bookings')

    // ── 2. Process each booking ──────────────────────────────────────────────
    const results = await Promise.allSettled(
      bookings.map((booking) => cancelBooking(booking, runLog)),
    )

    const succeeded = results.filter((r) => r.status === 'fulfilled').length
    const failed = results.filter((r) => r.status === 'rejected').length

    results.forEach((result, idx) => {
      if (result.status === 'rejected') {
        const booking = bookings[idx]
        runLog.error({ err: result.reason, bookingId: booking?.id }, 'auto-cancel: booking cancellation failed')
        Sentry.captureException(result.reason, { extra: { bookingId: booking?.id } })
      }
    })

    runLog.info({ succeeded, failed }, 'auto-cancel: run complete')
    Sentry.addBreadcrumb({ message: `auto-cancel-deposits: ${succeeded} cancelled, ${failed} failed`, level: 'info' })

  } catch (err: unknown) {
    runLog.error({ err }, 'auto-cancel: unexpected error in cron run')
    Sentry.captureException(err, { tags: { cron: 'auto-cancel-deposits' } })
  }
}

// ─── Per-booking cancellation ─────────────────────────────────────────────────

async function cancelBooking(booking: CancelledBookingRow, parentLog: ReturnType<typeof logger.child>): Promise<void> {
  const bookingLog = parentLog.child({ bookingId: booking.id, studioId: booking.studio_id })

  // ── Cancel in DB ─────────────────────────────────────────────────────────
  const { error: updateErr } = await supabase
    .from('bookings')
    .update({
      status: 'cancelled',
      cancelled_at: new Date().toISOString(),
      cancellation_reason: 'Deposit not paid within the required window',
      updated_at: new Date().toISOString(),
    })
    .eq('id', booking.id)
    .eq('status', 'pending')       // optimistic lock: only cancel if still pending
    .eq('deposit_paid', false)

  if (updateErr) {
    throw new Error(`DB update failed for booking ${booking.id}: ${updateErr.message}`)
  }

  bookingLog.info('auto-cancel: booking cancelled')

  // ── Resolve comm data for notifications ──────────────────────────────────
  const clientEmail = booking.client?.email
  const clientPhone = booking.client?.phone
  const clientFirstName = booking.client?.first_name ?? 'there'
  const studioName = booking.studio?.name ?? 'the studio'
  const serviceName = booking.service?.name ?? 'your session'
  const artistName = booking.artist?.display_name ?? 'your artist'

  // ── Enqueue email cancellation notification ───────────────────────────────
  if (clientEmail) {
    try {
      // Insert comm row first so it can be referenced
      const { data: commRow, error: commInsertErr } = await supabase
        .from('client_communications')
        .insert({
          studio_id: booking.studio_id,
          client_id: booking.client_id,
          booking_id: booking.id,
          channel: 'email',
          direction: 'outbound',
          template: 'booking_auto_cancelled',
          subject: `Your booking at ${studioName} has been cancelled`,
          body: `Hi ${clientFirstName}, your ${serviceName} booking at ${studioName} has been automatically cancelled because the deposit was not paid within the required window. Please contact the studio to rebook.`,
          status: 'queued',
          metadata: {},
        })
        .select('id')
        .single()

      if (commInsertErr || !commRow) {
        bookingLog.warn({ err: commInsertErr }, 'auto-cancel: failed to insert email comm row')
      } else {
        await enqueueJob('send-email', {
          to: clientEmail,
          template: 'booking_auto_cancelled',
          data: {
            studioName,
            clientFirstName,
            serviceName,
            artistName,
            scheduledAt: booking.scheduled_at,
          },
        })
        bookingLog.info({ commId: commRow.id }, 'auto-cancel: email job enqueued')
      }
    } catch (err: unknown) {
      bookingLog.warn({ err }, 'auto-cancel: email enqueue failed (non-fatal)')
    }
  }

  // ── Enqueue SMS cancellation notification (optional) ─────────────────────
  if (clientPhone) {
    try {
      const smsBody =
        `Hi ${clientFirstName}, your ${serviceName} on ` +
        `${new Date(booking.scheduled_at).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })} ` +
        `at ${studioName} was cancelled — deposit not received in time. ` +
        `Please contact us to rebook.`

      const { data: smsCommRow, error: smsInsertErr } = await supabase
        .from('client_communications')
        .insert({
          studio_id: booking.studio_id,
          client_id: booking.client_id,
          booking_id: booking.id,
          channel: 'sms',
          direction: 'outbound',
          template: 'booking_auto_cancelled',
          subject: null,
          body: smsBody,
          status: 'queued',
          metadata: {},
        })
        .select('id')
        .single()

      if (smsInsertErr || !smsCommRow) {
        bookingLog.warn({ err: smsInsertErr }, 'auto-cancel: failed to insert SMS comm row')
      } else {
        await enqueueJob('send-sms', {
          commId: smsCommRow.id,
          studioId: booking.studio_id,
        })
        bookingLog.info({ commId: smsCommRow.id }, 'auto-cancel: SMS job enqueued')
      }
    } catch (err: unknown) {
      bookingLog.warn({ err }, 'auto-cancel: SMS enqueue failed (non-fatal)')
    }
  }
}

/**
 * Deposit deadline reminder cron.
 *
 * Runs every 15 minutes.
 * Fires two reminders per booking:
 *   - 12h before deposit deadline (if not yet sent)
 *   - 4h before deposit deadline (if not yet sent)
 *
 * "Deposit deadline" = COALESCE(deposit_deadline_override, created_at + deadline_hours * interval '1 hour')
 *
 * Uses booking columns reminder_12h_sent_at / reminder_4h_sent_at as idempotency flags
 * (set by migration 20260421200000_booking_deposit_reminders.sql).
 */
import { supabase } from '../lib/supabase.js'
import { logger } from '../lib/logger.js'
import { Sentry } from '../lib/sentry.js'
import { enqueueJob } from '../lib/queue.js'

// ─── Types ───────────────────────────────────────────────────────────────────

type ReminderKind = '12h' | '4h'

interface ReminderBooking {
  id: string
  studio_id: string
  client_id: string
  scheduled_at: string
  deposit_cents: number
  reminder_12h_sent_at: string | null
  reminder_4h_sent_at: string | null
  effective_deadline: string
  client: {
    first_name: string
    email: string | null
    phone: string | null
  } | null
  service: {
    name: string
  } | null
  artist: {
    display_name: string
  } | null
  studio: {
    name: string
  } | null
}

// ─── Main handler ────────────────────────────────────────────────────────────

export async function runDepositDeadlineReminders(): Promise<void> {
  const runLog = logger.child({ cron: 'deposit-deadline-reminders' })
  runLog.info('reminders: checking for upcoming deposit deadlines')

  Sentry.addBreadcrumb({ message: 'deposit-deadline-reminders: run start', level: 'info' })

  try {
    const { data: rows, error } = await supabase
      .rpc('get_deposit_reminder_bookings')

    if (error) {
      runLog.error({ err: error }, 'reminders: RPC failed')
      Sentry.captureException(error, { tags: { cron: 'deposit-deadline-reminders' } })
      return
    }

    const bookings = (rows ?? []) as ReminderBooking[]

    if (bookings.length === 0) {
      runLog.info('reminders: no reminders due')
      return
    }

    runLog.info({ count: bookings.length }, 'reminders: processing')

    const results = await Promise.allSettled(
      bookings.map((booking) => sendReminderForBooking(booking, runLog)),
    )

    const succeeded = results.filter((r) => r.status === 'fulfilled').length
    const failed = results.filter((r) => r.status === 'rejected').length

    results.forEach((result, idx) => {
      if (result.status === 'rejected') {
        runLog.error({ err: result.reason, bookingId: bookings[idx]?.id }, 'reminders: booking reminder failed')
        Sentry.captureException(result.reason, { extra: { bookingId: bookings[idx]?.id } })
      }
    })

    runLog.info({ succeeded, failed }, 'reminders: run complete')

  } catch (err: unknown) {
    runLog.error({ err }, 'reminders: unexpected error')
    Sentry.captureException(err, { tags: { cron: 'deposit-deadline-reminders' } })
  }
}

// ─── Per-booking reminder logic ───────────────────────────────────────────────

async function sendReminderForBooking(booking: ReminderBooking, parentLog: ReturnType<typeof logger.child>): Promise<void> {
  const bookingLog = parentLog.child({ bookingId: booking.id, studioId: booking.studio_id })

  const now = Date.now()
  const deadlineMs = new Date(booking.effective_deadline).getTime()
  const msUntilDeadline = deadlineMs - now

  const hoursUntil = msUntilDeadline / (1_000 * 60 * 60)

  const needs12h = !booking.reminder_12h_sent_at && hoursUntil <= 12 && hoursUntil > 4
  const needs4h = !booking.reminder_4h_sent_at && hoursUntil <= 4 && hoursUntil > 0

  if (!needs12h && !needs4h) return

  const kind: ReminderKind = needs4h ? '4h' : '12h'
  bookingLog.info({ kind, hoursUntil: hoursUntil.toFixed(2) }, 'reminders: sending deposit reminder')

  const clientFirstName = booking.client?.first_name ?? 'there'
  const studioName = booking.studio?.name ?? 'the studio'
  const serviceName = booking.service?.name ?? 'your session'
  const artistName = booking.artist?.display_name ?? 'your artist'

  const hourLabel = kind === '12h' ? '12 hours' : '4 hours'
  const reminderBody =
    `Hi ${clientFirstName}, just a reminder: your deposit for ${serviceName} at ${studioName} is due in ${hourLabel}. ` +
    `Please pay to keep your slot. Contact us if you have questions.`

  const clientEmail = booking.client?.email
  const clientPhone = booking.client?.phone

  // ── Email reminder ────────────────────────────────────────────────────────
  if (clientEmail) {
    try {
      await enqueueJob('send-email', {
        to: clientEmail,
        template: kind === '12h' ? 'deposit_reminder_12h' : 'deposit_reminder_4h',
        data: {
          studioName,
          clientFirstName,
          serviceName,
          artistName,
          scheduledAt: booking.scheduled_at,
          deadlineAt: booking.effective_deadline,
        },
      })
      bookingLog.info({ kind }, 'reminders: email job enqueued')
    } catch (err: unknown) {
      bookingLog.warn({ err, kind }, 'reminders: email enqueue failed (non-fatal)')
    }
  }

  // ── SMS reminder ──────────────────────────────────────────────────────────
  if (clientPhone) {
    try {
      const { data: smsCommRow, error: smsInsertErr } = await supabase
        .from('client_communications')
        .insert({
          studio_id: booking.studio_id,
          client_id: booking.client_id,
          booking_id: booking.id,
          channel: 'sms',
          direction: 'outbound',
          template: kind === '12h' ? 'deposit_reminder_12h' : 'deposit_reminder_4h',
          subject: null,
          body: reminderBody,
          status: 'queued',
          metadata: {},
        })
        .select('id')
        .single()

      if (smsInsertErr || !smsCommRow) {
        bookingLog.warn({ err: smsInsertErr }, 'reminders: SMS comm insert failed')
      } else {
        await enqueueJob('send-sms', {
          commId: smsCommRow.id,
          studioId: booking.studio_id,
        })
        bookingLog.info({ kind, commId: smsCommRow.id }, 'reminders: SMS job enqueued')
      }
    } catch (err: unknown) {
      bookingLog.warn({ err, kind }, 'reminders: SMS enqueue failed (non-fatal)')
    }
  }

  // ── Mark reminder sent ────────────────────────────────────────────────────
  const sentAtField = kind === '12h' ? 'reminder_12h_sent_at' : 'reminder_4h_sent_at'
  const { error: markErr } = await supabase
    .from('bookings')
    .update({ [sentAtField]: new Date().toISOString(), updated_at: new Date().toISOString() })
    .eq('id', booking.id)
    .eq('deposit_paid', false)     // only mark if still unpaid (concurrent-safe)
    .eq('status', 'pending')

  if (markErr) {
    bookingLog.warn({ err: markErr, kind }, 'reminders: failed to mark reminder sent (non-fatal — may re-send once)')
  } else {
    bookingLog.info({ kind }, `reminders: ${kind} reminder marked sent`)
  }
}

/**
 * Worker-side job enqueuer — mirrors lib/queue.ts but uses direct BullMQ import.
 * Workers never import from next/* so we can't reuse the web app's queue module.
 *
 * Only used by cron workers that need to enqueue follow-up jobs (notifications).
 */
import { Queue } from 'bullmq'
import { workerEnv } from './env.js'
import { logger } from './logger.js'

const QUEUE_NAME = 'inkos-jobs'

// ─── Job payload types (mirror of lib/queue.ts) ───────────────────────────────

interface JobPayloadMap {
  'send-email': {
    to: string
    template: string
    data: Record<string, unknown>
  }
  'send-sms': {
    commId: string
    studioId: string
  }
}

type JobName = keyof JobPayloadMap

// ─── Lazy queue instance ──────────────────────────────────────────────────────

let _queue: Queue | null = null

function getQueue(): Queue {
  if (_queue) return _queue

  _queue = new Queue(QUEUE_NAME, {
    connection: {
      url: workerEnv.REDIS_URL,
      maxRetriesPerRequest: null,
    },
    defaultJobOptions: {
      attempts: 3,
      backoff: { type: 'exponential', delay: 5_000 },
      removeOnComplete: 100,
      removeOnFail: 500,
    },
  })

  return _queue
}

// ─── enqueueJob ───────────────────────────────────────────────────────────────

export async function enqueueJob<T extends JobName>(
  jobName: T,
  payload: JobPayloadMap[T],
  opts?: { delay?: number; priority?: number },
): Promise<{ id: string }> {
  const queue = getQueue()

  try {
    const job = await queue.add(jobName, payload, {
      ...(opts?.delay !== undefined && { delay: opts.delay }),
      ...(opts?.priority !== undefined && { priority: opts.priority }),
    })
    logger.info({ jobName, jobId: job.id }, 'queue: job enqueued from worker')
    return { id: job.id ?? `queued-${Date.now()}` }
  } catch (err: unknown) {
    logger.error({ err, jobName }, 'queue: failed to enqueue job from worker')
    throw err
  }
}

/**
 * Cron worker service entry point.
 *
 * Registers all scheduled jobs using node-cron.
 * Railway runs this as a separate service:
 *   Start command: pnpm -C workers cron
 *
 * Cron schedule reference:
 *   '*/10 * * * *'  → every 10 minutes
 *   '*/15 * * * *'  → every 15 minutes
 *   '0 * * * *'     → every hour at :00
 */
import cron from 'node-cron'
import { initSentry, Sentry } from '../lib/sentry.js'
import { logger } from '../lib/logger.js'
import { runAutoCancelDeposits } from './auto-cancel-deposits.js'
import { runDepositDeadlineReminders } from './deposit-deadline-reminders.js'

// ── Boot ────────────────────────────────────────────────────────────────────

initSentry()

logger.info('inkos-worker-cron: starting')

// ── Scheduled jobs ──────────────────────────────────────────────────────────

/**
 * Auto-cancel unpaid deposits — every 10 minutes.
 * Cancels bookings where deposit is overdue and appointment hasn't started.
 */
cron.schedule('*/10 * * * *', () => {
  logger.info('cron: running auto-cancel-deposits')
  runAutoCancelDeposits().catch((err: unknown) => {
    logger.error({ err }, 'cron: auto-cancel-deposits threw unexpectedly')
    Sentry.captureException(err)
  })
})

/**
 * Deposit deadline reminders — every 15 minutes.
 * Sends 12h and 4h reminders before the deposit deadline.
 */
cron.schedule('*/15 * * * *', () => {
  logger.info('cron: running deposit-deadline-reminders')
  runDepositDeadlineReminders().catch((err: unknown) => {
    logger.error({ err }, 'cron: deposit-deadline-reminders threw unexpectedly')
    Sentry.captureException(err)
  })
})

logger.info('inkos-worker-cron: all cron jobs scheduled')

// ── Graceful shutdown ───────────────────────────────────────────────────────

function shutdown(signal: string) {
  logger.info({ signal }, 'inkos-worker-cron: shutting down')
  process.exit(0)
}

process.on('SIGTERM', () => shutdown('SIGTERM'))
process.on('SIGINT', () => shutdown('SIGINT'))

