          </div>
          <Skeleton className="h-px w-full" />
          <div className="space-y-4">
            <Skeleton className="h-5 w-36" />
            <Skeleton className="h-10 w-48" />
            <Skeleton className="h-4 w-full max-w-md" />
          </div>
        </div>
      }
    >
      <BookingPoliciesContent />
    </Suspense>
