'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Clock } from 'lucide-react'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Button } from '@/components/ui/button'
import { Separator } from '@/components/ui/separator'
import { Typography } from '@/components/ui/typography'
import type { Database } from '@/lib/supabase/types'

type StudioPoliciesData = Pick<
  Database['public']['Tables']['studios']['Row'],
  'id' | 'deposit_deadline_hours'
>

interface BookingPoliciesClientProps {
  studio: StudioPoliciesData
  isOwner: boolean
}

export function BookingPoliciesClient({ studio, isOwner }: BookingPoliciesClientProps) {
  const router = useRouter()
  const [deadlineHours, setDeadlineHours] = useState<number>(studio.deposit_deadline_hours)
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)

  function handleHoursChange(raw: string) {
    const parsed = parseInt(raw, 10)
    if (!Number.isNaN(parsed)) {
      setDeadlineHours(parsed)
      setDirty(true)
    }
  }

  async function handleSave() {
    if (!isOwner) return

    // Clamp to DB constraint
    const clamped = Math.min(168, Math.max(1, deadlineHours))
    if (clamped !== deadlineHours) setDeadlineHours(clamped)

    setSaving(true)
    try {
      const res = await fetch(`/api/studios/${studio.id}/policies`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ deposit_deadline_hours: clamped }),
      })

      if (!res.ok) {
        const body = await res.json() as { error?: string }
        throw new Error(body.error ?? 'Failed to save')
      }

      toast.success('Booking policies saved')
      setDirty(false)
      router.refresh()
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'An error occurred'
      toast.error(msg)
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="flex items-start justify-between">
        <div className="space-y-1">
          <Typography variant="h1">Booking Policies</Typography>
          <p className="text-sm text-muted-foreground">
            Set deposit requirements and cancellation rules. Changes apply to new bookings only.
          </p>
        </div>
        {dirty && isOwner && (
          <span className="text-xs text-muted-foreground mt-1">Unsaved changes</span>
        )}
      </div>

      <Separator />

      {/* Deposit & Auto-cancel section */}
      <div className="space-y-6">
        <div>
          <h2 className="text-sm font-semibold">Deposits &amp; Auto-cancel</h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            Control how long clients have to pay their deposit before the slot is released.
          </p>
        </div>

        <div className="space-y-3 max-w-xs">
          <Label htmlFor="deposit-deadline" className="text-sm font-medium">
            <span className="flex items-center gap-1.5">
              <Clock className="h-3.5 w-3.5 text-muted-foreground" aria-hidden="true" />
              Hold slot for (hours awaiting deposit)
            </span>
          </Label>
          <Input
            id="deposit-deadline"
            type="number"
            min={1}
            max={168}
            value={deadlineHours}
            onChange={(e) => handleHoursChange(e.target.value)}
            disabled={!isOwner}
            className="w-32 tabular-nums"
            aria-describedby="deposit-deadline-desc"
          />
          <p id="deposit-deadline-desc" className="text-xs text-muted-foreground leading-relaxed max-w-sm">
            If the deposit is not paid within this window, the booking is automatically cancelled
            and the slot is freed for other clients. Minimum 1 hour, maximum 168 hours (7 days).
          </p>

          {/* Context pill */}
          <div className="inline-flex items-center gap-1.5 text-xs text-muted-foreground bg-muted/40 rounded-md px-2.5 py-1.5">
            <span>Current window:</span>
            <span className="font-semibold tabular-nums text-foreground">
              {deadlineHours >= 24
                ? `${(deadlineHours / 24).toFixed(deadlineHours % 24 === 0 ? 0 : 1)} day${deadlineHours === 24 ? '' : 's'}`
                : `${deadlineHours} hour${deadlineHours === 1 ? '' : 's'}`}
            </span>
          </div>
        </div>
      </div>

      {isOwner && (
        <>
          <Separator />
          <div className="flex justify-end">
            <Button
              onClick={() => void handleSave()}
              disabled={saving || !dirty}
              size="sm"
            >
              {saving ? 'Saving…' : 'Save changes'}
            </Button>
          </div>
        </>
      )}

      {!isOwner && (
        <p className="text-xs text-muted-foreground">
          Only studio owners and admins can change booking policies.
        </p>
      )}
    </div>
  )
}

/**
 * PATCH /api/studios/[id]/policies
 *
 * Updates studio-level booking policies (deposit_deadline_hours).
 * Auth guard: owner or admin role only.
 * Rate limited: authedRatelimit (10 req/min per user).
 */
import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const bodySchema = z.object({
  deposit_deadline_hours: z
    .number({ invalid_type_error: 'deposit_deadline_hours must be a number' })
    .int()
    .min(1, 'Minimum 1 hour')
    .max(168, 'Maximum 168 hours (7 days)'),
})

interface RouteParams {
  params: Promise<{ id: string }>
}

export async function PATCH(req: NextRequest, { params }: RouteParams) {
  const { id: studioId } = await params

  // ── Rate limit ──────────────────────────────────────────────────────────────
  const ip = req.headers.get('x-forwarded-for') ?? '127.0.0.1'
  const { success: rateLimitOk } = await authedRatelimit.limit(ip)
  if (!rateLimitOk) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  // ── Auth ────────────────────────────────────────────────────────────────────
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // ── Authorization: owner or admin only ─────────────────────────────────────
  if (auth.studioId !== studioId) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }
  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'Only owners and admins can change booking policies' }, { status: 403 })
  }

  // ── Parse body ──────────────────────────────────────────────────────────────
  let rawBody: unknown
  try {
    rawBody = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const parsed = bodySchema.safeParse(rawBody)
  if (!parsed.success) {
    return NextResponse.json(
      { error: parsed.error.errors.map((e) => e.message).join(', ') },
      { status: 422 },
    )
  }

  const { deposit_deadline_hours } = parsed.data

  // ── Update ──────────────────────────────────────────────────────────────────
  const supabase = await createClient()
  const { error } = await supabase
    .from('studios')
    .update({ deposit_deadline_hours, updated_at: new Date().toISOString() })
    .eq('id', studioId)

  if (error) {
    logger.error({ err: error, studioId }, 'policies: DB update failed')
    return NextResponse.json({ error: 'Failed to save policies' }, { status: 500 })
  }

  logger.info({ studioId, deposit_deadline_hours }, 'policies: updated')
  return NextResponse.json({ ok: true })
}

/**
 * PATCH /api/bookings/[id]/extend-deadline
 *
 * Admin override: sets deposit_deadline_override on a pending booking.
 * Body: { hours: number }  — extends from now() by `hours` hours.
 *       OR { until: string } — explicit ISO 8601 timestamp.
 *
 * Auth: owner or admin only.
 */
import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const bodySchema = z.union([
  z.object({
    hours: z.number().int().positive().max(720, 'Maximum 720 hours (30 days)'),
  }),
  z.object({
    until: z.string().datetime({ message: 'until must be a valid ISO 8601 datetime' }),
  }),
])

interface RouteParams {
  params: Promise<{ id: string }>
}

export async function PATCH(req: NextRequest, { params }: RouteParams) {
  const { id: bookingId } = await params

  // ── Rate limit ──────────────────────────────────────────────────────────────
  const ip = req.headers.get('x-forwarded-for') ?? '127.0.0.1'
  const { success: rateLimitOk } = await authedRatelimit.limit(ip)
  if (!rateLimitOk) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  // ── Auth ────────────────────────────────────────────────────────────────────
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'Only owners and admins can extend deposit deadlines' }, { status: 403 })
  }

  // ── Parse body ──────────────────────────────────────────────────────────────
  let rawBody: unknown
  try {
    rawBody = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const parsed = bodySchema.safeParse(rawBody)
  if (!parsed.success) {
    return NextResponse.json(
      { error: parsed.error.errors.map((e) => e.message).join(', ') },
      { status: 422 },
    )
  }

  // ── Compute new deadline ────────────────────────────────────────────────────
  let newDeadline: Date
  if ('hours' in parsed.data) {
    newDeadline = new Date(Date.now() + parsed.data.hours * 60 * 60 * 1_000)
  } else {
    newDeadline = new Date(parsed.data.until)
  }

  if (newDeadline <= new Date()) {
    return NextResponse.json({ error: 'New deadline must be in the future' }, { status: 422 })
  }

  // ── Fetch booking to verify studio membership ───────────────────────────────
  const supabase = await createClient()
  const { data: booking, error: fetchErr } = await supabase
    .from('bookings')
    .select('id, studio_id, status, deposit_paid')
    .eq('id', bookingId)
    .single()

  if (fetchErr || !booking) {
    return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
  }

  if (booking.studio_id !== auth.studioId) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  if (booking.status !== 'pending') {
    return NextResponse.json({ error: 'Can only extend deadline on pending bookings' }, { status: 409 })
  }

  if (booking.deposit_paid) {
    return NextResponse.json({ error: 'Deposit is already paid' }, { status: 409 })
  }

  // ── Update ──────────────────────────────────────────────────────────────────
  const { error: updateErr } = await supabase
    .from('bookings')
    .update({
      deposit_deadline_override: newDeadline.toISOString(),
      // Reset 4h reminder so client receives a fresh one before the new deadline
      reminder_4h_sent_at: null,
      updated_at: new Date().toISOString(),
    })
    .eq('id', bookingId)

  if (updateErr) {
    logger.error({ err: updateErr, bookingId }, 'extend-deadline: DB update failed')
    return NextResponse.json({ error: 'Failed to extend deadline' }, { status: 500 })
  }

  logger.info({ bookingId, studioId: auth.studioId, newDeadline }, 'extend-deadline: updated')
  return NextResponse.json({ ok: true, deadline: newDeadline.toISOString() })
}

/**
 * Email sender — Resend transactional email client.
 *
 * Falls back to a warning log when RESEND_API_KEY is absent (local dev).
 * In production, RESEND_API_KEY must be set or emails silently drop with a log.
 */
import { Resend } from 'resend'
import { render } from '@react-email/components'
import { logger } from '@/lib/logger'

export const FROM_EMAIL = process.env.RESEND_FROM_EMAIL ?? 'notifications@inkos.app'
export const REPLY_TO = process.env.RESEND_REPLY_TO ?? 'support@inkos.app'

// ─── Template registry ───────────────────────────────────────────────────────

export type EmailTemplate =
  | 'booking_confirmation'
  | 'booking_reminder_24h'
  | 'booking_reminder_2h'
  | 'deposit_received'
  | 'session_aftercare'
  | 'invoice_paid'
  | 'payment_failed'
  // Sprint 13 A3 — deposit auto-cancel
  | 'booking_auto_cancelled'
  | 'deposit_reminder_12h'
  | 'deposit_reminder_4h'

// Per-template data shapes — typed so callers get compile-time errors on missing fields.
// Dates are ISO strings because they come from JSON payloads (queue jobs).
export interface BookingConfirmationData {
  studioName: string
  clientFirstName: string
  serviceName: string
  artistName: string
  scheduledAt: string     // ISO 8601
  endAt: string           // ISO 8601
  durationMin: number
  priceCents: number
  depositCents: number
  depositPaid: boolean
  bookingReference: string
  depositPaymentUrl?: string
}

export interface BookingReminderData {
  studioName: string
  studioAddress?: string
  clientFirstName: string
  serviceName: string
  artistName: string
  scheduledAt: string     // ISO 8601
  endAt: string           // ISO 8601
  durationMin: number
  cancellationPolicyHours?: number
  bookingReference: string
}

export interface DepositReceivedData {
  studioName: string
  clientFirstName: string
  serviceName: string
  artistName: string
  scheduledAt: string     // ISO 8601
  depositCents: number
  bookingReference: string
}

export interface InvoicePaidData {
  studioName: string
  clientFirstName: string
  amountCents: number
  invoiceId: string
  receiptUrl?: string
}

export interface PaymentFailedData {
  studioName: string
  clientFirstName: string
  amountCents: number
  retryDate?: string
  updatePaymentUrl?: string
}

// Sprint 13 A3 — deposit auto-cancel templates
export interface BookingAutoCancelledData {
  studioName: string
  clientFirstName: string
  serviceName: string
  artistName: string
  scheduledAt: string  // ISO 8601
  [key: string]: unknown
}

export interface DepositReminderData {
  studioName: string
  clientFirstName: string
  serviceName: string
  artistName: string
  scheduledAt: string  // ISO 8601
  deadlineAt: string   // ISO 8601 — when deposit must be paid by
  [key: string]: unknown
}

type TemplateDataMap = {
  booking_confirmation: BookingConfirmationData
  booking_reminder_24h: BookingReminderData
  booking_reminder_2h: BookingReminderData
  deposit_received: DepositReceivedData
  session_aftercare: BookingReminderData
  invoice_paid: InvoicePaidData
  payment_failed: PaymentFailedData
  // Sprint 13 A3
  booking_auto_cancelled: BookingAutoCancelledData
  deposit_reminder_12h: DepositReminderData
  deposit_reminder_4h: DepositReminderData
}

export interface SendEmailParams<T extends EmailTemplate> {
  to: string
  template: T
  data: TemplateDataMap[T]
}

// ─── Template subjects ───────────────────────────────────────────────────────
const SUBJECTS: Record<EmailTemplate, string> = {
  booking_confirmation: 'Your booking is confirmed',
  booking_reminder_24h: 'Reminder: Your appointment is tomorrow',
  booking_reminder_2h: 'Reminder: Your appointment is in 2 hours',
  deposit_received: 'Deposit received — you\'re all set',
  session_aftercare: 'Aftercare instructions for your session',
  invoice_paid: 'Payment confirmed',
  payment_failed: 'Action needed: Payment failed',
  // Sprint 13 A3
  booking_auto_cancelled: 'Your booking has been cancelled — deposit not received',
  deposit_reminder_12h: 'Reminder: Deposit due in 12 hours',
  deposit_reminder_4h: 'Urgent: Deposit due in 4 hours',
}

// ─── Lazy Resend client ──────────────────────────────────────────────────────
let _resend: Resend | null = null

function getResendClient(): Resend | null {
  const key = process.env.RESEND_API_KEY
  if (!key) return null
  if (!_resend) _resend = new Resend(key)
  return _resend
}

// ─── Template renderer ───────────────────────────────────────────────────────
async function renderTemplate(
  template: EmailTemplate,
  data: TemplateDataMap[EmailTemplate],
): Promise<string> {
  switch (template) {
    case 'booking_confirmation': {
      const { BookingConfirmationEmail } = await import('./templates/booking-confirmation')
      const d = data as BookingConfirmationData
      return render(
        BookingConfirmationEmail({
          ...d,
          scheduledAt: new Date(d.scheduledAt),
          endAt: new Date(d.endAt),
        }),
      )
    }

    case 'booking_reminder_24h':
    case 'booking_reminder_2h':
    case 'session_aftercare': {
      const { Reminder24hEmail } = await import('./templates/reminder-24h')
      const d = data as BookingReminderData
      const reminderProps: Parameters<typeof Reminder24hEmail>[0] = {
        studioName: d.studioName,
        clientFirstName: d.clientFirstName,
        serviceName: d.serviceName,
        artistName: d.artistName,
        scheduledAt: new Date(d.scheduledAt),
        endAt: new Date(d.endAt),
        durationMin: d.durationMin,
      }
      // Conditionally spread optional fields to satisfy exactOptionalPropertyTypes
      if (d.studioAddress !== undefined) reminderProps.studioAddress = d.studioAddress
      if (d.cancellationPolicyHours !== undefined) reminderProps.cancellationPolicyHours = d.cancellationPolicyHours
      return render(Reminder24hEmail(reminderProps))
    }

    case 'deposit_received': {
      const { DepositReceiptEmail } = await import('./templates/deposit-receipt')
      const d = data as DepositReceivedData
      return render(
        DepositReceiptEmail({
          studioName: d.studioName,
          clientFirstName: d.clientFirstName,
          serviceName: d.serviceName,
          artistName: d.artistName,
          scheduledAt: new Date(d.scheduledAt),
          depositCents: d.depositCents,
          bookingReference: d.bookingReference,
        }),
      )
    }

    case 'invoice_paid': {
      const { InvoicePaidEmail } = await import('./templates/invoice-paid')
      return render(InvoicePaidEmail(data as InvoicePaidData))
    }

    case 'payment_failed': {
      const { PaymentFailedEmail } = await import('./templates/payment-failed')
      return render(PaymentFailedEmail(data as PaymentFailedData))
    }

    // ── Sprint 13 A3 — inline HTML templates (full React templates in Sprint 14) ──

    case 'booking_auto_cancelled': {
      const d = data as BookingAutoCancelledData
      const scheduledDate = new Date(d.scheduledAt).toLocaleDateString('en-US', {
        weekday: 'long', month: 'long', day: 'numeric',
      })
      return `
        <div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:24px">
          <h2 style="color:#111">Booking Cancelled</h2>
          <p>Hi ${d.clientFirstName},</p>
          <p>Your <strong>${d.serviceName}</strong> booking with ${d.artistName} at
            <strong>${d.studioName}</strong> scheduled for ${scheduledDate} has been
            automatically cancelled because the deposit was not received within the required
            window.</p>
          <p>Please contact the studio to rebook — we'd love to see you.</p>
          <p style="color:#666;font-size:13px">— ${d.studioName}</p>
        </div>
      `
    }

    case 'deposit_reminder_12h':
    case 'deposit_reminder_4h': {
      const d = data as DepositReminderData
      const hoursLabel = template === 'deposit_reminder_12h' ? '12 hours' : '4 hours'
      const scheduledDate = new Date(d.scheduledAt).toLocaleDateString('en-US', {
        weekday: 'long', month: 'long', day: 'numeric',
      })
      const deadlineTime = new Date(d.deadlineAt).toLocaleTimeString('en-US', {
        hour: '2-digit', minute: '2-digit',
      })
      return `
        <div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:24px">
          <h2 style="color:#111">Deposit Due in ${hoursLabel}</h2>
          <p>Hi ${d.clientFirstName},</p>
          <p>Your deposit for <strong>${d.serviceName}</strong> with ${d.artistName}
            at <strong>${d.studioName}</strong> (${scheduledDate}) is due by
            <strong>${deadlineTime}</strong>.</p>
          <p>To keep your slot, please pay your deposit before the deadline.
            Contact the studio directly if you have questions.</p>
          <p style="color:#666;font-size:13px">— ${d.studioName}</p>
        </div>
      `
    }

    default: {
      const _exhaustive: never = template
      throw new Error(`Unknown email template: ${String(_exhaustive)}`)
    }
  }
}

// ─── sendEmail ───────────────────────────────────────────────────────────────

export async function sendEmail<T extends EmailTemplate>(
  params: SendEmailParams<T>,
): Promise<{ id: string }> {
  const client = getResendClient()

  if (!client) {
    logger.warn(
      { to: params.to, template: params.template },
      'email skipped — RESEND_API_KEY not set (set it in .env.local)',
    )
    return { id: `noop-${Date.now()}` }
  }

  let html: string
  try {
    html = await renderTemplate(
      params.template,
      params.data as TemplateDataMap[EmailTemplate],
    )
  } catch (err) {
    logger.error({ err, template: params.template }, 'email: template render failed')
    throw err
  }

  const { data, error } = await client.emails.send({
    from: FROM_EMAIL,
    replyTo: REPLY_TO,
    to: params.to,
    subject: SUBJECTS[params.template],
    html,
  })

  if (error) {
    logger.error({ error, to: params.to, template: params.template }, 'email: send failed')
    throw new Error(`Resend error: ${error.message}`)
  }

  logger.info({ id: data?.id, to: params.to, template: params.template }, 'email: sent')
  return { id: data?.id ?? `sent-${Date.now()}` }
}

